import{_ as p,a as i}from"./chunks/cg-xjlb3.2d4b72fa.js";import{_ as a,o as t,c as e,O as o}from"./chunks/framework.ac0f74f3.js";const r="/assets/cg-xjlb1.a8812bbf.png",b=JSON.parse('{"title":"询价列表","description":"","frontmatter":{},"headers":[],"relativePath":"采购管理/询价列表.md","filePath":"采购管理/询价列表.md"}'),s={name:"采购管理/询价列表.md"};function u(n,l,c,_,h,d){return t(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="询价列表" tabindex="-1">询价列表 <a class="header-anchor" href="#询价列表" aria-label="Permalink to &quot;询价列表&quot;">​</a></h1><blockquote><p>“询价列表”位于采购管理板块，在&quot;询价列表&quot;中可向供方新增 &quot;询价单&quot; 可保存草稿，保存的草稿支持删除</p></blockquote><h4 id="_1-新增询价" tabindex="-1">1.新增询价 <a class="header-anchor" href="#_1-新增询价" aria-label="Permalink to &quot;1.新增询价&quot;">​</a></h4><ul><li><p>新增询价单包括</p><p>-直接新建询价单</p><p>-选择之前模板列表中所保存的询价单模板</p><p>-缺料列表发起的询价</p></li></ul><h4 id="_2-询价单状态" tabindex="-1">2.询价单状态 <a class="header-anchor" href="#_2-询价单状态" aria-label="Permalink to &quot;2.询价单状态&quot;">​</a></h4><ul><li><p>询价单状态分为，已询价， 未报价、草稿</p><p>-未报价 : 新增的询价单确认后界面显示未报价</p><p>-已报价：新增的询价单会发送到供方哪里，在供方销售部的 “询价单列表进行处理以后，显示 “已报价”状态</p><p>-草稿：新增的询价单点击保存草稿，显示草稿状态</p></li></ul><h4 id="_3-删除功能" tabindex="-1">3.删除功能 <a class="header-anchor" href="#_3-删除功能" aria-label="Permalink to &quot;3.删除功能&quot;">​</a></h4><ul><li>草稿状态下的询价单支持删除</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_4-新增询价单" tabindex="-1">4.新增询价单 <a class="header-anchor" href="#_4-新增询价单" aria-label="Permalink to &quot;4.新增询价单&quot;">​</a></h4><ul><li><p>供方信息：来源于采购管理,供应商列表中添加的客户信息</p></li><li><p>关联公司：供方/需方可通过下拉框选择关联公司，同时会根据选择的关联公司，进行信息的更换</p><p>-使用关联公司时，签章时所用的印章为关联公司印章。（关联公司印章也需要设置后对人员进行授权）</p></li><li><p>供方联系人 : 来源于供应商列表中添加的联系人(可添加多个联系人)</p></li><li><p>类型 : 来源于财务管理,汇率税率列表中添加的汇率税率信息</p></li><li><p>选择产品 : 产品来源于所添加供应商公司产品列表中的产品（可输入产品点击&quot;对号&quot;图标创建产品字段）</p><p>-可在需方/供方之间切换选择产品</p></li><li><p>点击选择按钮可在弹窗中批量选择产品进行录入</p></li><li><p>点击打印设置按钮可设定打印宽度</p></li><li><p>批量导入：可批量导入产品（先下载模板Excel进行编辑导入即可）</p></li><li><p>编辑名称:点击编辑名称按钮可对询价单的名称进行编辑</p></li><li><p>小眼睛图标：指的是页面中需方/供方列表中的小眼睛图标，默认全展示，可选择关闭或者打开（如果关闭对方将无法看到这条信息，包括打印和下载都不展示）</p></li><li><p>小笔图标：文字傍边带有小笔图标的方可编辑</p></li><li><p>下载图标：点击下载图标可下载当前页面内容</p></li><li><p>打印图标：点击可打印当前页面的信息</p></li><li><p>使用提示：点击使用提示可弹出弹窗，在弹窗中显示动图，可切换查看对应功能的使用（新增字段，批量修改价格，调整宽度，签章显示，签章不显示）</p></li></ul><p><img src="'+p+'" alt="如图所示"></p><ul><li><p>货期：点击选择货期时间，支持一键录入货期</p></li><li><p>内部型号：点击选择内部型号（选择自己公司对应的产品，物料）</p><p>-悬浮显示产品的编号型号</p></li><li><p>历史报价 : 跟同个公司询价过同个产品时，如果再次询价就会显示之前的产品历史报价信息</p></li><li><p>历史成交价 : 跟同个公司成交过这个产品，成功以后再次询价时会显示之前的产品历史成交价</p></li><li><p>单价/总计小数点位数显示：根据汇率税率列表中设置的小数位数显示小数位数</p><p>-（例如：设置的小数位数是2位，产品列表中单价，总价显示的金额位数是两位）</p></li><li><p>总计 : 是所添加的产品单价的总计(支持更改单价添加公式(加 , 减 , 乘(乘的是百分比，1就是0.01) 输入数值)</p></li><li><p>字段更改 : 在添加产品信息以后可以悬浮对应的产品信息如果出现&quot;更改的小笔图标&quot;就代表可以更改这个产品的信息内容,或者双击也可以更改</p></li><li><p>产品查询：支持查询已添加的产品信息</p></li><li><p>备注：可输入询价信息的备注</p></li><li><p>存为模板 : 如果点击存为模板在模板列表中显示所存的模板</p></li><li><p>确认:如果点击确认,询价单将发送给供方，询价列表显示状态&quot;未报价&quot;</p></li><li><p>保存草稿 : 点击保存草稿,在询价列表显示状态为 &quot;草稿&quot;</p></li></ul><p><img src="'+i+'" alt="如图所示"></p>',14)])])}const f=a(s,[["render",u]]);export{b as __pageData,f as default};
